#nullable enable // autogenerated

using System.Collections.Generic;
using System.Xml;

namespace MVZ2.Metas
{
    public class CustomizeMetaList
    {
        public CustomizePageMeta[] pages;

        public CustomizeMetaList(CustomizePageMeta[] pages)
        {
            this.pages = pages;
        }

        public static CustomizeMetaList FromXmlNode(XmlNode node, string defaultNsp)
        {
            var pages = new List<CustomizePageMeta>();
            for (int i = 0; i < node.ChildNodes.Count; i++)
            {
                var childNode = node.ChildNodes[i];
                switch (childNode.Name)
                {
                    case "pages":
                        LoadPagesFromXmlNode(childNode, defaultNsp, pages);
                        break;
                }
            }
            return new CustomizeMetaList(pages.ToArray());
        }
        private static void LoadPagesFromXmlNode(XmlNode node, string defaultNsp, List<CustomizePageMeta> pages)
        {
            for (int i = 0; i < node.ChildNodes.Count; i++)
            {
                var childNode = node.ChildNodes[i];
                switch (childNode.Name)
                {
                    case "page":
                        var meta = CustomizePageMeta.FromXmlNode(childNode, defaultNsp);
                        if (meta != null)
                        {
                            pages.Add(meta);
                        }
                        break;
                }
            }
        }
    }
}
